-- Seed the hazard register from the paper registers (178 rows). Generated by tools/hazard_seed.py – re-runnable (upserts on ref).
insert into public.hazards (ref, runs, area, address, kinds, severity, rule, note, control, source)
select ref, case rk when 'r' then array['RSB','WH'] when 'p' then array['PCB','WH'] when 'b' then array['RSB','PCB','WH'] when 'o' then array['RAM'] when 'u' then array['FLY','TUA'] else array['FLY','TUA','RAM'] end,
  area, address, array[k], case s when 'h' then 'high' when 'm' then 'medium' else 'low' end, rule, note,
  case ctl when '#D' then 'Do not deliver if worried about personal safety. Card to depot. Attempt delivery to the mailbox if able.' when '#I' then 'Black ice: change down a gear, don''t use the foot brake. If a road is too dangerous, don''t deliver – tell the owner and SDM. Walking pace on foot in poor conditions.' when '#M' then 'Wait left if there''s space and slowing is safe at speed. Consider following traffic, light, road and weather. Don''t deliver if it''s unsafe.' else ctl end,
  case when ref like 'WH-%' then 'West Harbour risk register (Greg handover, 25 Sep 2026)' else 'Taieri Post risk register – site-specific data (Aug 2025)' end
from (values
('WH-001','r','Roseneath','District Road – 20 & 24A','access','l','CAUTION','Up a private road about 50 m along District Road; hard to find, numbers out of sequence','Both sit up the private road – easy to miss with food boxes. Second 24A is at the END of the road.'),
('WH-002','r','Roseneath','District Road – 24A (end of road)','person','m','CARD','Difficult customer – on Greg''s risk register; Greg does not deliver to the house','Card it. Eunice may have been delivering – give her one chance, then card if any issue.'),
('WH-003','r','Roseneath','District Road – bottom of road (near 46)','ice','m','WET/ICE-NO','Bottom of District Road ices up in winter','Winter only. If icy, don''t attempt the bottom section.'),
('WH-004','r','Roseneath','46 District Road','access','l','CARD','House about 1 km off the road','Card it. Parcels can be left by the letterbox.'),
('WH-005','r','Roseneath','Prospect Row – all','driveway','m','CAUTION','Very tight – big van cannot turn around','Reverse straight out (or nose into No. 6 and reverse back). Bottom of Prospect slides shut in winter ice.'),
('WH-006','r','Roseneath','6 Prospect Row','driveway','l','CAUTION','Tricky driveway; gets a lot of parcels','Enter only to turn; reverse out.'),
('WH-007','r','Roseneath','Clyde Street – 4 & 6A','driveway','h','CARD','Do not go down – NZ Post (Andrea & Mo) have agreed these are carded','Never drive down. Card anything that doesn''t fit the letterbox. Cards go to Port Chalmers.'),
('WH-008','r','Roseneath','20 Clyde Street','driveway','m','CARD','Wheelspin on the driveway; under discussion with NZ Post (Andrea) – Greg and Eunice both card it','Card until NZ Post/customer sort a box at the road.'),
('WH-009','r','Roseneath','Cove Street – all (1A–8)','driveway','h','WET/ICE-NO','Steep hill – you will not get back up when it is wet, even with parcels','Never go down when wet. Not in a HiAce at all (rear-wheel drive). If stuck: back to the flat, first gear, keep momentum.'),
('WH-010','r','Roseneath','Fraser Street – 10 & 12','access','l','INFO','Two houses up a shared driveway on the right','No need to drive up – walk. Dead end at the bottom.'),
('WH-011','r','Roseneath','Kilgour Street – all (1–14)','driveway','h','WALK','Most dangerous street in Roseneath – steep, narrow, nowhere to turn; No. 14 at the very top gets a lot of parcels','Stop short and walk the last part to 14. To turn: nose into No. 10''s garage driveway and reverse (only once confident) – otherwise reverse all the way down. Not in the wet. New drivers: reverse only for the first 2 months.'),
('WH-012','r','Roseneath','Roseneath street receiver – bottom of Kilgour','info','l','INFO','Street receiver clearance','Last job in Roseneath.'),
('WH-013','r','Roseneath','34 Noyna Road','access','l','INFO','Confusing address – sits by itself on the left across the road; hard to find','If in doubt bring it back or ring Greg.'),
('WH-014','r','Roseneath','Noyna Road – 20–28 cluster (20, 22, 24, 24A, 26, 28)','driveway','m','CAUTION','Houses craned in on an incline; letterboxes together; nowhere to turn – Greg has nearly been stuck several times','When in doubt reverse out. Do not use the driveways to turn (incline). Empty van loses traction easily.'),
('WH-015','r','Sawyers Bay','Station Road – 33 → roundabout','info','l','INFO','Runs high to low from 33 to the roundabout',null),
('WH-016','r','Sawyers Bay','Freyberg Avenue – all','info','l','INFO','One-way; addresses mainly on the right – pick up the left as you go. Light mail: park once and do a handful on foot',null),
